const RATES = [1.0, 1.25, 1.5, 1.75, 2.0];

function setSpeakingCard(card) {
    document.querySelectorAll('.card.currently-speaking').forEach(c => c.classList.remove('currently-speaking'));
    if (card) card.classList.add('currently-speaking');
}

// ===== ГОЛОСА =====
let voices = [];
let selectedVoice = null;

if ('speechSynthesis' in window) {
    loadVoices();
    speechSynthesis.onvoiceschanged = loadVoices;
}

function loadVoices() {
    voices = speechSynthesis.getVoices();
    const menu = document.getElementById('voiceMenu');
    if (!menu) return;
    const ruVoices = voices.filter(v => v.lang.startsWith('ru'));
    const targetVoices = ruVoices.length > 0 ? ruVoices : voices;
    menu.innerHTML = '';
    const autoItem = document.createElement('button');
    autoItem.className = 'dropdown-item' + (selectedVoice === null ? ' active' : '');
    autoItem.textContent = 'Выбор озвучки (автоматически)';
    autoItem.dataset.voice = '';
    autoItem.addEventListener('click', () => selectVoice(null));
    menu.appendChild(autoItem);
    targetVoices.forEach(voice => {
        const item = document.createElement('button');
        item.className = 'dropdown-item' + (selectedVoice && selectedVoice.name === voice.name ? ' active' : '');
        item.textContent = `${voice.name} (${voice.lang})`;
        item.dataset.voice = voice.name;
        item.addEventListener('click', () => selectVoice(voice));
        menu.appendChild(item);
    });
    updateVoiceToggleText();
}

function selectVoice(voice) {
    selectedVoice = voice;
    document.querySelectorAll('#voiceMenu .dropdown-item').forEach(el => el.classList.remove('active'));
    if (voice) {
        const target = document.querySelector(`#voiceMenu .dropdown-item[data-voice="${voice.name}"]`);
        if (target) target.classList.add('active');
    } else {
        document.querySelector('#voiceMenu .dropdown-item[data-voice=""]')?.classList.add('active');
    }
    updateVoiceToggleText();
    if (speechSynthesis.speaking) speechSynthesis.cancel();
    closeAllDropdowns();
}

function updateVoiceToggleText() {
    const toggle = document.getElementById('voiceToggle');
    if (!toggle) return;
    const text = selectedVoice ? `${selectedVoice.name} (${selectedVoice.lang})` : 'Выбор голоса';
    toggle.innerHTML = `${text} <span class="arrow">▼</span>`;
}

// ===== ФУНКЦИИ ДЛЯ КНОПКИ "ПОКАЗАТЬ ПОЛНОСТЬЮ" =====
function updateExpandButtonVisibility(card) {
    const content = card.querySelector('.card-content');
    const btnWrapper = card.querySelector('.expand-btn-wrapper');
    if (!content || !btnWrapper) return;

    // В режиме теста — не трогаем, там свои правила
    if (card.classList.contains('quiz-mode')) return;

    // Раскрытая карточка — кнопка "Свернуть" всегда видна
    if (card.classList.contains('expanded')) {
        btnWrapper.style.display = 'block';
        return;
    }

    // Свёрнутая — показываем "Показать полностью" только если контент не влезает
    const hasScroll = content.scrollHeight > content.clientHeight + 1;
    btnWrapper.style.display = hasScroll ? 'block' : 'none';
}

function scheduleUpdateExpandButton(card) {
    requestAnimationFrame(() => {
        requestAnimationFrame(() => {
            setTimeout(() => updateExpandButtonVisibility(card), 20);
        });
    });
}

function updateAllVisibleCardsButtons() {
    document.querySelectorAll('.card:not(.hidden)').forEach(card => scheduleUpdateExpandButton(card));
}

function observeCardContent(card) {
    const content = card.querySelector('.card-content');
    if (!content) return;
    const resizeObserver = new ResizeObserver(() => scheduleUpdateExpandButton(card));
    resizeObserver.observe(content);
    const mutationObserver = new MutationObserver(() => scheduleUpdateExpandButton(card));
    mutationObserver.observe(content, { childList: true, subtree: true, attributes: false });
    card._resizeObserver = resizeObserver;
    card._mutationObserver = mutationObserver;
}

function resetAllDropdownTitles() {
    Object.keys(DEFAULT_DROPDOWN_TEXTS).forEach(id => {
        const toggle = document.getElementById(id);
        if (toggle) {
            toggle.innerHTML = DEFAULT_DROPDOWN_TEXTS[id];
            toggle.classList.remove('active');
        }
    });
}

const controls = document.querySelector('.controls');
let progressWrapper = null;

function createProgressBar() {
    if (!progressWrapper) {
        progressWrapper = document.createElement('div');
        progressWrapper.className = 'progress-wrapper';
        progressWrapper.innerHTML = `
            <span class="progress-text">0%</span>
            <div class="progress-track">
                <div class="progress-fill" style="width: 0%;"></div>
            </div>
        `;
        const statsEl = document.querySelector('.controls .stats');
        if (statsEl) statsEl.after(progressWrapper);
        else controls.appendChild(progressWrapper);
    }
}

function updateProgressBar(percent) {
    if (!progressWrapper) createProgressBar();
    const fill = progressWrapper.querySelector('.progress-fill');
    const text = progressWrapper.querySelector('.progress-text');
    if (!fill || !text) return;
    const terms = getTermsForCurrentFilter();
    if (currentFilter === 'all' || terms.length === 0) {
        progressWrapper.style.display = 'none';
        return;
    }
    progressWrapper.style.display = 'flex';
    const progress = Math.min(100, Math.max(0, percent));
    fill.style.width = progress + '%';
    text.textContent = Math.round(progress) + '%';
    fill.className = 'progress-fill';
}

function escapeHtml(text) {
    if (!text) return '';
    const div = document.createElement('div');
    div.textContent = text;
    return div.innerHTML;
}

function removeDuplicates(data) {
    const seen = new Set();
    const unique = [];
    data.forEach(item => {
        const key = `${item.term}|${item.category}`;
        if (!seen.has(key)) {
            seen.add(key);
            unique.push(item);
        }
    });
    //if (unique.length < data.length) {
    //    console.warn(`⚠️ Найдено и удалено ${data.length - unique.length} дублирующихся записей`);
    //}
    return unique;
}

function getTermsForCurrentFilter() {
    if (typeof TERMS_DATA === 'undefined') return [];
    // Объединяем: базовые (с overrides) + кастомные, минус скрытые
    const base   = TERMS_DATA.map(getEffectiveCard);
    const all    = [...base, ...window.customCards]
                    .filter(function (c) { return window.hiddenCardIds.indexOf(c.id) === -1; });
    const unique = removeDuplicates(all);
    if (currentFilter === 'all') return unique;
    return unique.filter(function (item) { return item.category === currentFilter; });
}

function isCurrentFilterComplete() {
    if (currentFilter === 'all') return false;
    const terms = getTermsForCurrentFilter();
    if (terms.length === 0) return false;
    return terms.every(item => learnedCards[item.id] !== undefined);
}

function collectStatsForCurrentFilter() {
    if (currentFilter === 'all' || typeof TERMS_DATA === 'undefined') {
        return { total: 0, known: 0, unknown: 0, knownTerms: [], unknownTerms: [] };
    }
    const terms = getTermsForCurrentFilter();
    const stats = {
        total: terms.length,
        known: 0,
        unknown: 0,
        knownTerms: [],
        unknownTerms: []
    };
    terms.forEach(item => {
        const status = learnedCards[item.id];
        if (status) {
            if (status.known) { stats.known++; stats.knownTerms.push(item.term); }
            else { stats.unknown++; stats.unknownTerms.push(item.term); }
        } else {
            stats.unknown++;
            stats.unknownTerms.push(item.term);
        }
    });
    return stats;
}

function renderSummaryForCurrentFilter() {
    if (currentFilter === 'all' || typeof TERMS_DATA === 'undefined') {
        swipeSummary.style.display = 'none';
        return;
    }
    const stats = collectStatsForCurrentFilter();
    const filterLabel = FILTER_LABELS[currentFilter] || currentFilter;
    const header = document.querySelector('#swipeSummary h3');
    if (header) header.textContent = `Итоги по разделу «${filterLabel}»`;
    const badge = document.querySelector('.summary-badge');
    if (badge) badge.textContent = `${stats.total} терминов`;
    const total = stats.total, known = stats.known, unknown = stats.unknown;
    const remaining = total - known - unknown;
    const percent = total > 0 ? Math.round((known / total) * 100) : 0;
    const progressBar = document.querySelector('.summary-progress-bar');
    if (progressBar) progressBar.style.width = percent + '%';
    const statTotal = document.getElementById('statTotal');
    const statKnown = document.getElementById('statKnown');
    const statUnknown = document.getElementById('statUnknown');
    const statRemaining = document.getElementById('statRemaining');
    if (statTotal) statTotal.textContent = total;
    if (statKnown) statKnown.textContent = known;
    if (statUnknown) statUnknown.textContent = unknown;
    if (statRemaining) statRemaining.textContent = remaining;
    if (knownListEl) {
        let html = `<h4>✅ Знаю (${known})</h4>`;
        if (known > 0) html += `<ul>${stats.knownTerms.map(t => `<li>${escapeHtml(t)}</li>`).join('')}</ul>`;
        else html += `<p style="color: #888;">Нет выученных терминов</p>`;
        knownListEl.innerHTML = html;
    }
    if (unknownListEl) {
        let html = `<h4>❌ Нужно повторить (${unknown})</h4>`;
        if (unknown > 0) html += `<ul>${stats.unknownTerms.map(t => `<li>${escapeHtml(t)}</li>`).join('')}</ul>`;
        else html += `<p style="color: #888;">Все термины выучены! 🎉</p>`;
        unknownListEl.innerHTML = html;
    }
    swipeSummary.style.display = 'block';
}

function updateStudyProgress() {
    const terms = getTermsForCurrentFilter();
    let total = terms.length, known = 0, unknown = 0;
    terms.forEach(item => {
        const status = learnedCards[item.id];
        if (status) {
            if (status.known) known++;
            else unknown++;
        }
    });
    const remaining = total - (known + unknown);
    const percent = total > 0 ? (known / total) * 100 : 0;
    let statsEl = document.querySelector('.study-stats');
    if (!statsEl) {
        const statsBlock = document.querySelector('.controls .stats');
        if (statsBlock) {
            statsEl = document.createElement('span');
            statsEl.className = 'study-stats';
            statsBlock.after(statsEl);
        }
    }
    if (statsEl) {
        const topicName = FILTER_LABELS[currentFilter] || currentFilter;
        statsEl.innerHTML = `<strong>${topicName}</strong>: Всего: ${total} | ✅ Знаю: ${known} | ❌ Не знаю: ${unknown} | 📖 Осталось: ${remaining}`;
    }
    updateProgressBar(percent);
}

function refreshSummary() {
    if (isCurrentFilterComplete()) renderSummaryForCurrentFilter();
    else swipeSummary.style.display = 'none';
    updateStudyProgress();
}

function resetCurrentFilterStatsAndRefresh() {
    if (currentFilter === 'all' || typeof TERMS_DATA === 'undefined') return;
    const terms = getTermsForCurrentFilter();
    terms.forEach(item => delete learnedCards[item.id]);
    localStorage.setItem('myLearnedCards', JSON.stringify(learnedCards));
    swipeSummary.style.display = 'none';
    renderCards(getTermsForCurrentFilter());
    filterAndSearch();
}

function stripHtml(html) {
    if (!html) return '';
    const tmp = document.createElement('div');
    tmp.innerHTML = html;
    return tmp.textContent || tmp.innerText || '';
}

function cleanText(text) {
    if (!text) return '';
    return text.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
}

// ================================================================
//  РЕНДЕРИНГ КАРТОЧЕК (С ТРЕМЯ РЕЖИМАМИ)
// ================================================================

function renderCards(data) {
    if (!data || data.length === 0) {
        cardsGrid.innerHTML = '<p style="text-align:center; padding:40px; color:#888;">Нет данных для отображения</p>';
        return;
    }
    // Применяем overrides и убираем скрытые
    const mergedData = data.map(getEffectiveCard)
                          .filter(function (c) { return window.hiddenCardIds.indexOf(c.id) === -1; 
    });
    const uniqueData = removeDuplicates(mergedData);
    cardsGrid.innerHTML = '';
    
    uniqueData.forEach(item => {
        const card = document.createElement('div');
        card.className = 'card';
        card.dataset.id = item.id;
        card.dataset.category = item.category;
        card.dataset.term = item.term.toLowerCase();

        /* if (learnedCards[item.id]) {
            card.classList.add('hidden');
        }*/

        const metaHtml = item.meta ? item.meta.map(m => `<span class="meta">${escapeHtml(m)}</span>`).join('') : '';
        const sectionBadge = item.section
            ? `<span class="meta" style="background:#e1ebf9;color:#0a1929;escapeHtml(item.section)}</span>`
            : '';

        let academicText = '';
        if (Array.isArray(item.academic)) {
            academicText = `<ul>${item.academic.map(point => `<li>${escapeHtml(point)}</li>`).join('')}</ul>`;
        } else {
            academicText = item.academic || '';
        }

        let exampleHtml = item.example || '';
        if (!exampleHtml.includes('<ul') && !exampleHtml.includes('<ol')) {
            exampleHtml = exampleHtml.replace(/\n/g, '<br>');
        }

        card.innerHTML = `
                <div class="card-header">
                    <div class="term-row">
                        <span class="term">${escapeHtml(item.term)}</span>
                    </div>
                    <div class="meta-row">
                        <span class="tag ${item.tagColor}">${escapeHtml(item.tag)}</span>
                        <span class="mode-badge" id="modeBadge_${item.id}">Определение</span>
                    </div>
                </div>

            <div class="card-content">
                <div class="definition" id="def_${item.id}" style="display: none;">
                    <div class="simple-def"><strong>Обобщённое:</strong> ${item.simple || ''}</div>
                    <div class="example"><strong>Пример:</strong><br>${exampleHtml}</div>
                    <span class="source">${escapeHtml(item.source || '')}</span>
                </div>
                <div class="academic-definition" id="acad_${item.id}">
                    <div class="academic-text">
                        <strong>Определение:</strong><br>
                        ${academicText}
                    </div>
                    <span class="source">${escapeHtml(item.source || '')}</span>
                </div>
                <div class="quiz-container" id="quiz_${item.id}" style="display: none;">
                    <div class="quiz-question" id="quizQuestion_${item.id}">Введите термин</div>
                    <div class="quiz-input-wrapper">
                        <textarea class="quiz-input" id="quizInput_${item.id}" placeholder="Напишите ответ..." rows=""></textarea>
                        <button class="quiz-voice-btn" id="quizVoice_${item.id}" title="Голосовой ввод">🎙️</button>
                    </div>
                    <div class="quiz-action-row">
                        <button class="quiz-check-btn" id="quizCheck_${item.id}">Проверить</button>
                        <button class="quiz-hint-btn" id="quizHint_${item.id}" title="Подсказка">💡</button>
                    </div>
                    <div class="quiz-result" id="quizResult_${item.id}"></div>
                    <div class="quiz-hint-content" id="quizHintContent_${item.id}" style="display: none;"></div>
                </div>
                <div class="meta-tags" style="display: none;">${sectionBadge}${metaHtml}</div>
            </div>

            <!-- Кнопка "Проверь себя" внизу -->
            <div class="quiz-toggle-wrapper">
                <button class="quiz-toggle-btn" id="quizToggle_${item.id}">Проверь себя</button>
            </div>

            <div class="card-actions">
                <button class="edit-card-btn ${item._isOverridden ? 'modified' : ''}"
                        data-edit-id="${item.id}"
                        title="${item._isOverridden ? 'Изменена (можно вернуть)' : 'Редактировать'}">
                    ${item._isOverridden ? 'Изменить' : 'Редактировать'}
                </button>
                <button class="delete-card-btn"
                        data-delete-id="${item.id}"
                        title="Удалить / Скрыть">
                    ${item.id >= 10000 ? 'Удалить' : 'Скрыть'}
                </button>
            </div>

            <div class="expand-btn-wrapper">
                <button class="expand-btn">Показать полностью ▼</button>
            </div>
        `;

        cardsGrid.appendChild(card);
        
        // ===== Кнопки редактирования и удаления для ВСЕХ карточек =====
        const editBtnEl = card.querySelector('.edit-card-btn');
        if (editBtnEl) {
            editBtnEl.addEventListener('click', function (e) {
                e.stopPropagation();
                e.preventDefault();
                window.editAnyCard(parseInt(this.dataset.editId));
            });
        }
        const deleteBtnEl = card.querySelector('.delete-card-btn');
        if (deleteBtnEl) {
            deleteBtnEl.addEventListener('click', function (e) {
                e.stopPropagation();
                e.preventDefault();
                window.deleteAnyCard(parseInt(this.dataset.deleteId));
            });
        }

        // ===== ЛОГИКА ОЗВУЧКИ =====
        if ('speechSynthesis' in window) {
            const metaRow = card.querySelector('.meta-row');
            const controls = document.createElement('div');
            controls.className = 'speed-controls';

            const speedBtn = document.createElement('button');
            speedBtn.className = 'speed-btn';
            speedBtn.textContent = '1x';
            speedBtn.title = 'Скорость озвучки';

            speedBtn.addEventListener('click', (e) => {
                e.stopPropagation();
                globalRateIndex = (globalRateIndex + 1) % RATES.length;
                const newRate = RATES[globalRateIndex];
                speedBtn.textContent = newRate === 1.0 ? '1x' : newRate + 'x';

                if (activeSpeech && activeSpeech.card === card && activeSpeech.isPlaying) {
                    const position = activeSpeech.position;
                    const text = activeSpeech.text;
                    if (activeSpeech.utterance) speechSynthesis.cancel();
                    const remainingText = text.substring(position);
                    const utterance = new SpeechSynthesisUtterance(remainingText);
                    utterance.lang = 'ru-RU';
                    utterance.rate = newRate;
                    if (selectedVoice) utterance.voice = selectedVoice;
                    const newId = ++utteranceCounter;
                    activeSpeech.currentUtteranceId = newId;
                    utterance.onboundary = (event) => {
                        if (activeSpeech && activeSpeech.currentUtteranceId === newId) {
                            activeSpeech.position = event.charIndex + (text.length - remainingText.length);
                        }
                    };
                    utterance.onend = () => {
                        if (activeSpeech && activeSpeech.currentUtteranceId === newId) {
                            activeSpeech.isPlaying = false;
                            activeSpeech.isPaused = false;
                            if (activeSpeech.btn) {
                                activeSpeech.btn.classList.remove('speaking');
                                activeSpeech.btn.innerHTML = '🔊';
                            }
                            activeSpeech.utterance = null;
                            if (activeSpeech.card === card) setSpeakingCard(null);
                        }
                    };
                    utterance.onerror = () => {
                        if (activeSpeech && activeSpeech.currentUtteranceId === newId) {
                            activeSpeech.isPlaying = false;
                            activeSpeech.isPaused = false;
                            if (activeSpeech.btn) {
                                activeSpeech.btn.classList.remove('speaking');
                                activeSpeech.btn.innerHTML = '🔊';
                            }
                            activeSpeech.utterance = null;
                            if (activeSpeech.card === card) setSpeakingCard(null);
                        }
                    };
                    speechSynthesis.speak(utterance);
                    activeSpeech.utterance = utterance;
                    activeSpeech.isPlaying = true;
                    activeSpeech.isPaused = false;
                    if (activeSpeech.btn) {
                        activeSpeech.btn.innerHTML = '⏸';
                        activeSpeech.btn.classList.add('speaking');
                    }
                    setSpeakingCard(card);
                }
            });

            const speakBtn = document.createElement('button');
            speakBtn.className = 'speak-btn';
            speakBtn.innerHTML = '🔊';
            speakBtn.title = 'Озвучить / Пауза';

            speakBtn.addEventListener('click', (e) => {
                e.stopPropagation();

                if (activeSpeech && activeSpeech.card !== card && activeSpeech.isPlaying) {
                    if (activeSpeech.utterance) speechSynthesis.cancel();
                    if (activeSpeech.btn) {
                        activeSpeech.btn.classList.remove('speaking');
                        activeSpeech.btn.innerHTML = '🔊';
                    }
                    activeSpeech.isPlaying = false;
                    activeSpeech.isPaused = false;
                    activeSpeech.utterance = null;
                }

                if (activeSpeech && activeSpeech.card === card) {
                    if (activeSpeech.isPlaying && !activeSpeech.isPaused) {
                        speechSynthesis.pause();
                        activeSpeech.isPaused = true;
                        activeSpeech.btn.innerHTML = '▶';
                        return;
                    } else if (activeSpeech.isPlaying && activeSpeech.isPaused) {
                        speechSynthesis.resume();
                        activeSpeech.isPaused = false;
                        activeSpeech.btn.innerHTML = '⏸';
                        return;
                    } else {
                        activeSpeech.isPlaying = false;
                        activeSpeech.isPaused = false;
                        activeSpeech.position = 0;
                        setSpeakingCard(null);
                    }
                }

                const term = card.querySelector('.term')?.textContent || '';
                const simpleDefBlock = card.querySelector('.definition');
                const academicDefBlock = card.querySelector('.academic-definition');
                let textToSpeak = term;
                if (simpleDefBlock && simpleDefBlock.style.display !== 'none') {
                    const simpleText = simpleDefBlock.querySelector('.simple-def')?.textContent || '';
                    const exampleText = simpleDefBlock.querySelector('.example')?.textContent || '';
                    textToSpeak += `. ${simpleText}. ${exampleText}`;
                } else if (academicDefBlock && academicDefBlock.style.display !== 'none') {
                    const academicText = academicDefBlock.querySelector('.academic-text')?.textContent || '';
                    textToSpeak += `. ${academicText}`;
                }
                if (textToSpeak === term) {
                    const simpleFallback = card.querySelector('.simple-def')?.textContent || '';
                    const academicFallback = card.querySelector('.academic-text')?.textContent || '';
                    textToSpeak += `. ${simpleFallback} ${academicFallback}`;
                }

                if (!activeSpeech) activeSpeech = {};
                activeSpeech.card = card;
                activeSpeech.btn = speakBtn;
                activeSpeech.text = textToSpeak;
                activeSpeech.position = 0;
                activeSpeech.isPlaying = true;
                activeSpeech.isPaused = false;

                const rate = RATES[globalRateIndex];
                speedBtn.textContent = rate === 1.0 ? '1x' : rate + 'x';
                const utterance = new SpeechSynthesisUtterance(textToSpeak);
                utterance.lang = 'ru-RU';
                utterance.rate = rate;
                if (selectedVoice) utterance.voice = selectedVoice;

                const newId = ++utteranceCounter;
                activeSpeech.currentUtteranceId = newId;
                utterance.onboundary = (event) => {
                    if (activeSpeech && activeSpeech.currentUtteranceId === newId) {
                        activeSpeech.position = event.charIndex;
                    }
                };
                utterance.onend = () => {
                    if (activeSpeech && activeSpeech.currentUtteranceId === newId) {
                        activeSpeech.isPlaying = false;
                        activeSpeech.isPaused = false;
                        activeSpeech.btn.classList.remove('speaking');
                        activeSpeech.btn.innerHTML = '🔊';
                        activeSpeech.utterance = null;
                        if (activeSpeech.card === card) setSpeakingCard(null);
                    }
                };
                utterance.onerror = () => {
                    if (activeSpeech && activeSpeech.currentUtteranceId === newId) {
                        activeSpeech.isPlaying = false;
                        activeSpeech.isPaused = false;
                        activeSpeech.btn.classList.remove('speaking');
                        activeSpeech.btn.innerHTML = '🔊';
                        activeSpeech.utterance = null;
                        if (activeSpeech.card === card) setSpeakingCard(null);
                    }
                };
                speechSynthesis.speak(utterance);
                activeSpeech.utterance = utterance;
                speakBtn.innerHTML = '⏸';
                speakBtn.classList.add('speaking');
                setSpeakingCard(card);
            });

            controls.appendChild(speedBtn);
            controls.appendChild(speakBtn);
            metaRow.appendChild(controls);
        }

        // ===== СТАРТОВЫЙ ВИД =====
        card.querySelector('.definition').style.display = 'none';
        card.querySelector('.academic-definition').style.display = 'block';
        const badge = card.querySelector('.mode-badge');
        badge.style.background = '#0a1929';
        badge.style.color = 'white';
        const metaTags = card.querySelector('.meta-tags');
        if (metaTags) metaTags.style.display = 'none';
        card.classList.add('mode-only-definition');

        // ===== ССЫЛКИ =====
        const simpleDef = card.querySelector('.definition');
        const academicDef = card.querySelector('.academic-definition');
        const quizContainer = card.querySelector('.quiz-container');
        const quizToggleBtn = card.querySelector('.quiz-toggle-btn');
        const quizInput = card.querySelector('.quiz-input');
        const quizCheckBtn = card.querySelector('.quiz-check-btn');
        const quizResult = card.querySelector('.quiz-result');
        const quizHintBtn = card.querySelector('.quiz-hint-btn');
        const quizHintContent = card.querySelector('.quiz-hint-content');
        const quizVoiceBtn = card.querySelector('.quiz-voice-btn');
        const quizQuestion = card.querySelector('.quiz-question');

        // ===== ЗАРАНЕЕ ГОТОВИМ ТЕКСТ ДЛЯ ПРОВЕРКИ =====
        let referenceText = '';
        if (item.simple) referenceText += ' ' + item.simple;
        if (Array.isArray(item.academic)) {
            referenceText += ' ' + item.academic.join(' ');
        } else if (item.academic) {
            referenceText += ' ' + item.academic;
        }
        if (item.example) {
            const plainExample = item.example.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
            referenceText += ' ' + plainExample;
        }
        referenceText = referenceText.toLowerCase().replace(/[^а-яa-z0-9\s]/g, ' ').replace(/\s+/g, ' ').trim();

        // ===== ФУНКЦИЯ ОЦЕНКИ ОТВЕТА =====
        // ===== ВСПОМОГАТЕЛЬНЫЕ ФУНКЦИИ ДЛЯ УМНОЙ ПРОВЕРКИ =====
        function normalizeWord(word) {
            let w = word.toLowerCase();
            if (EXTRA_SYNONYMS[w]) return EXTRA_SYNONYMS[w];
            if (SYNONYM_MAP[w]) return SYNONYM_MAP[w];
            // Грубый стеммер: берём первые 5 символов
            if (w.length > 5) return w.slice(0, 5);
            return stemRussian(w);
        }

        function extractKeywords(text) {
            const cleaned = cleanText(text);
            const words = cleaned.toLowerCase().split(/\s+/).filter(w => w.length > 2 && !STOP_WORDS.has(w));
            const set = new Set();
            words.forEach(raw => {
                let w = raw.replace(/[^а-яa-z0-9]/g, '');
                if (!w || STOP_WORDS.has(w)) return;
                w = normalizeWord(w);
                set.add(w);
            });
            return set;
        }

        function countMatches(userSet, targetSet) {
            if (targetSet.size === 0) return 0;
            let matches = 0;
            userSet.forEach(word => {
                if (targetSet.has(word)) matches++;
            });
            return Math.round((matches / targetSet.size) * 100);
        }

        const STOP_WORDS = new Set([
            'того', 'что', 'это', 'в', 'на', 'и', 'для', 'по', 'с', 'к', 'о', 'об', 'из', 'от',
            'как', 'так', 'же', 'а', 'но', 'или', 'не', 'да', 'нет', 'был', 'была', 'было',
            'были', 'его', 'её', 'их', 'мы', 'вы', 'они', 'он', 'она', 'оно', 'я', 'ты',
            'которые', 'который', 'которая', 'которое', 'этого', 'этому', 'этом', 'эти',
            'более', 'менее', 'очень', 'также', 'при', 'через', 'между', 'под', 'над', 'про'
        ]);

        const EXTRA_SYNONYMS = {
            'соответствует': 'соответств',
            'соответствовать': 'соответств',
            'соответствие': 'соответств',
            'согласно': 'соответств',
            'требованиям': 'требован',
            'требования': 'требован',
            'разработан': 'создан',
            'создан': 'создан',
            'ожиданиям': 'ожидан',
            'пользователя': 'пользовател',
            'валидация': 'валидац',
            'подтверждение': 'подтвержд',
            
        };

        // ===== ВСПОМОГАТЕЛЬНЫЕ ФУНКЦИИ ДЛЯ УМНОЙ ПРОВЕРКИ =====
        function normalizeWord(word) {
            let w = word.toLowerCase();
            if (EXTRA_SYNONYMS[w]) return EXTRA_SYNONYMS[w];
            if (SYNONYM_MAP[w]) return SYNONYM_MAP[w];
            return stemRussian(w);
        }

        function cleanText(text) {
            if (!text) return '';
            return text
                .replace(/<[^>]*>/g, ' ')
                .replace(/class="[^"]*"/g, '')
                .replace(/\s+/g, ' ')
                .trim();
        }

        function extractKeywords(text) {
            const cleaned = cleanText(text);
            const words = cleaned.toLowerCase().split(/\s+/).filter(w => w.length > 2 && !STOP_WORDS.has(w));
            const set = new Set();
            words.forEach(raw => {
                let w = raw.replace(/[^а-яa-z0-9]/g, '');
                if (!w || STOP_WORDS.has(w)) return;
                w = normalizeWord(w);
                set.add(w);
            });
            return set;
        }

        function countMatches(userSet, targetSet) {
            if (targetSet.size === 0) return 0;
            let matches = 0;
            userSet.forEach(word => {
                if (targetSet.has(word)) matches++;
            });
            return Math.round((matches / targetSet.size) * 100);
        }

        // ===== УЛУЧШЕННАЯ ФУНКЦИЯ ОЦЕНКИ ОТВЕТА =====
        function getAnswerScore(userAnswer) {
            const userWords = extractKeywords(userAnswer);
            if (userWords.size === 0) return { score: 0, missing: [] };

            // Ключевые слова из всех частей карточки
            const academicWords = extractKeywords(academicText || '');
            const simpleWords = extractKeywords(item.simple || '');
            const exampleWords = extractKeywords(item.example || '');
            const allCardWords = new Set([...academicWords, ...simpleWords, ...exampleWords]);

            // Считаем, сколько слов ответа найдено в определении
            let matched = 0;
            userWords.forEach(word => {
                if (allCardWords.has(word)) matched++;
            });

            // Базовый процент = доля слов ответа, которые есть в определении
            let score = (matched / userWords.size) * 100;

            // Штраф за короткий ответ (менее 3 значимых слов)
            if (userWords.size < 3) {
                score = Math.min(score, 60);
            }
            // Штраф за ответ, состоящий только из термина (например, "Обеспечение качества")
            const termWords = extractKeywords(item.term);
            const isOnlyTerm = userWords.size <= termWords.size + 1 && matched >= userWords.size - 1;
            if (isOnlyTerm) {
                score = Math.min(score, 40);
            }

            // Ограничиваем 100%
            score = Math.min(100, Math.round(score));

            // Пропущенные слова
            const missing = [];
            allCardWords.forEach(word => {
                if (!userWords.has(word)) missing.push(word);
            });

            return { score: score, missing: missing.slice(0, 7) };
        }

        function getHintText(item) {
            const parts = [];

            // ---- Академическое определение ----
            if (item.academic) {
                let academicText = Array.isArray(item.academic) ? item.academic.join(' ') : item.academic;
                academicText = stripHtml(academicText);
                const lines = academicText.split('\n').filter(s => s.trim().length > 0);
                let firstLines = lines.slice(0, 2).join(' ');
                if (firstLines.length > 100) firstLines = firstLines.slice(0, 100) + '…';
                if (firstLines) {
                    parts.push(`<strong><span class="mark-blue">Определение:</span></strong> ${firstLines}`);
                }
            }

            // ---- Пример ----
            if (item.example) {
                let exampleText = stripHtml(item.example);
                const lines = exampleText.split('\n').filter(s => s.trim().length > 0);
                let firstLines = lines.slice(0, 2).join(' ');
                if (firstLines.length > 100) firstLines = firstLines.slice(0, 100) + '…';
                if (firstLines) {
                    parts.push(`<strong><span class="mark-orange">Пример:</span></strong> ${firstLines}`);
                }
            }

            // ---- Запасной вариант ----
            if (parts.length === 0) {
                if (item.meta && item.meta.length > 0) {
                    return item.meta.join(', ');
                }
                const sourceText = cleanText(item.simple || '');
                if (sourceText) {
                    const words = sourceText.split(' ').filter(w => w.length > 2);
                    return words.slice(0, 7).join(' ') + '…';
                }
                return 'Нет подсказки';
            }

            // Объединяем части с переносом строки
            return parts.join('<br>');
        }

        // Вспомогательная функция для удаления HTML-тегов
        function stripHtml(html) {
            const tmp = document.createElement('div');
            tmp.innerHTML = html;
            return tmp.textContent || tmp.innerText || '';
        }

                // ===== РЕЖИМЫ =====
        function showQuiz() {
            // ---- Сохраняем текущий режим ----
            const isSimple = simpleDef.style.display !== 'none';
            card._modeBeforeTest = isSimple ? 'simple' : 'academic';

            // ---- Переключаем в тест ----
            simpleDef.style.display = 'none';
            academicDef.style.display = 'none';
            quizContainer.style.display = 'block';
            badge.textContent = 'Проверь себя';
            badge.style.background = '#6a1b9a';
            badge.style.color = 'white';
            metaTags.style.display = 'none';
            card.classList.remove('mode-only-definition');
            card.classList.add('quiz-mode');

            // ---- Вопрос ----
            const useExample = Math.random() > 0.5;
            if (useExample) {
                const exampleText = simpleDef.querySelector('.example')?.textContent || '';
                // Очищаем текст от HTML-тегов и обрезаем до 80 символов
                const cleanExample = exampleText.replace(/<[^>]*>/g, '').trim().replace(/^Пример:\s*/i, '').substring(0, 80);
                // Оборачиваем первые 5 слов в маркер (можно изменить количество)
                const highlighted = highlightKeywords(cleanExample, 5);
                // Вставляем через innerHTML, чтобы теги работали
                quizQuestion.innerHTML = 'Опишите своими словами, что такое "' + item.term + '"? (Похоже на: ' + highlighted + '...)';
            } else {
                quizQuestion.textContent = 'Что такое "' + item.term + '"?';
            }
            quizInput.value = '';
            quizResult.textContent = '';
            quizHintContent.style.display = 'none';
            quizToggleBtn.textContent = 'Вернуться'; // или 'Назад'

        }

        function hideQuiz() {
            // ---- Скрываем тест ----
            quizContainer.style.display = 'none';

            // ---- Восстанавливаем сохранённый режим ----
            const mode = card._modeBeforeTest || 'academic';
            if (mode === 'simple') {
                simpleDef.style.display = 'block';
                academicDef.style.display = 'none';
                badge.textContent = 'Пример';
                badge.style.background = '#e6edf6';
                badge.style.color = '#1a2a3a';
                metaTags.style.display = 'flex';
                card.classList.remove('mode-only-definition');
            } else {
                academicDef.style.display = 'block';
                simpleDef.style.display = 'none';
                badge.textContent = 'Определение';
                badge.style.background = '##0a1929';
                badge.style.color = 'white';
                metaTags.style.display = 'none';
                card.classList.add('mode-only-definition');
            }
            card.classList.remove('quiz-mode');
            // (не удаляем _modeBeforeTest, чтобы можно было использовать повторно, но можно и удалить)
            quizToggleBtn.textContent = 'Проверь себя'; // или 'Повторить'
        }

        // ---- Сохраняем функции на карточке ----
        card._showQuiz = showQuiz;
        card._hideQuiz = hideQuiz;

        // ===== ОБРАБОТЧИКИ =====

        
        // ===== ОБРАБОТЧИК КНОПКИ ПОДСКАЗКИ (💡) =====
        const hintBtn = document.getElementById('quizHint_' + item.id);
        if (hintBtn) {
            hintBtn.addEventListener('click', function(e) {
                e.stopPropagation(); // чтобы случайно не сработало что-то ещё

                const hintContent = document.getElementById('quizHintContent_' + item.id);
                if (hintContent) {
                    // Переключаем видимость: если скрыт – показываем и заполняем, если виден – скрываем
                    if (hintContent.style.display === 'none') {
                        // Заполняем содержимое
                        const hintText = getHintText(item); // вызываем функцию с текущим item
                        hintContent.innerHTML = hintText.replace(/\n/g, '<br>'); // переносы строк в <br>
                        hintContent.style.display = 'block';
                    } else {
                        hintContent.style.display = 'none';
                    }
                }
            });
        }

        quizToggleBtn.addEventListener('click', function(e) {
            e.stopPropagation();
            e.preventDefault();
            
            // Убираем блокировку – полагаемся на скрытие кнопки
            if (!card.classList.contains('quiz-mode')) {
                showQuiz();
            } else {
                hideQuiz();
            }
            scheduleUpdateExpandButton(card);
        });

        quizCheckBtn.addEventListener('click', async function(e) {
        e.stopPropagation();
        e.preventDefault();
        const userAnswer = quizInput.value.trim();
        if (!userAnswer) return;

        quizResult.innerHTML = '⏳ Проверяю...';

        // Получаем текст правильного ответа (простое определение)
        const correctText = `${item.academic || ''} ${item.example || ''}`.trim();
        const score = await evaluateWithAI(userAnswer, item.term, item);

        // Сохраняем результат
        handleTestResult(item, card, score);

        // Отображаем результат
        let msg = '';
        if (score >= 80) msg = `✅ Отлично! Вы передали смысл на ${score}%`;
        else if (score >= 50) msg = `⚠️ Неплохо, но можно лучше! Совпадение ${score}%`;
        else msg = `❌ Пока рано! Совпадение ${score}%`;

        quizResult.innerHTML = msg;

        // Показываем правильный ответ
        simpleDef.style.display = 'none';
        academicDef.style.display = 'none';
        //const defToShow = simpleDef.style.display !== 'none' ? simpleDef : academicDef;
        //defToShow.style.display = 'block';
        });

        // ===== ГОЛОСОВОЙ ВВОД (с диагностикой) =====
        if ('webkitSpeechRecognition' in window || 'SpeechRecognition' in window) {
            const SpeechRecognition = window.webkitSpeechRecognition || window.SpeechRecognition;
            const recognition = new SpeechRecognition();
            recognition.lang = 'ru-RU';
            recognition.interimResults = false;

            const voiceBtn = document.getElementById('quizVoice_' + item.id);
            if (!voiceBtn) return;

            voiceBtn.addEventListener('click', function(e) {
                e.stopPropagation();
                e.preventDefault();

                if (this.dataset.listening === 'true') {
                    console.log('⏳ Распознавание уже идёт');
                    return;
                }

                // Запрашиваем микрофон
                if (navigator.mediaDevices && navigator.mediaDevices.getUserMedia) {
                    this.textContent = '⏳';
                    this.dataset.listening = 'true';
                    this.title = 'Запрос микрофона...';

                    navigator.mediaDevices.getUserMedia({ audio: true })
                        .then(function(stream) {
                            // Успешно получили доступ к микрофону
                            console.log('✅ Микрофон доступен');
                            // Запускаем распознавание
                            recognition.start();
                            voiceBtn.textContent = '⏳';
                            voiceBtn.title = 'Слушаю...';
                            // Останавливаем треки, они не нужны
                            stream.getTracks().forEach(track => track.stop());
                        })
                        .catch(function(err) {
                            console.error('❌ Ошибка доступа к микрофону:', err.name, err.message);
                            voiceBtn.textContent = '❌';
                            voiceBtn.dataset.listening = 'false';
                            voiceBtn.title = 'Ошибка микрофона';
                            // Показываем понятное сообщение
                            let msg = 'Не удалось получить доступ к микрофону.\n\n';
                            if (err.name === 'NotAllowedError' || err.name === 'PermissionDeniedError') {
                                msg += 'Разрешите доступ в настройках браузера (иконка замка в адресной строке).';
                            } else if (err.name === 'NotFoundError' || err.name === 'DevicesNotFoundError') {
                                msg += 'Микрофон не найден. Проверьте, что он подключён и включён.';
                            } else if (err.name === 'NotReadableError' || err.name === 'TrackStartError') {
                                msg += 'Микрофон занят другим приложением (например, Zoom, Skype). Закройте другие программы, использующие микрофон.';
                            } else {
                                msg += 'Ошибка: ' + err.message;
                            }
                            alert(msg);
                            setTimeout(() => {
                                voiceBtn.textContent = '🎙️';
                                voiceBtn.title = 'Голосовой ввод';
                            }, 3000);
                        });
                } else {
                    // Если getUserMedia не поддерживается
                    alert('Ваш браузер не поддерживает голосовой ввод. Используйте Chrome или Edge.');
                }
            });

            recognition.onresult = function(event) {
                const transcript = event.results[0][0].transcript;
                const input = document.getElementById('quizInput_' + item.id);
                if (input) {
                    input.value = transcript;
                    input.dispatchEvent(new Event('input', { bubbles: true }));
                }
                voiceBtn.textContent = '🎙️';
                voiceBtn.dataset.listening = 'false';
                voiceBtn.title = 'Голосовой ввод';
                console.log('🎤 Распознано:', transcript);
            };

            recognition.onerror = function(event) {
                console.error('❌ Ошибка распознавания:', event.error);
                voiceBtn.textContent = '❌';
                voiceBtn.dataset.listening = 'false';
                voiceBtn.title = 'Ошибка распознавания';
                let msg = '';
                switch (event.error) {
                    case 'audio-capture':
                        msg = 'Ошибка захвата звука.\n\nВозможные причины:\n- Микрофон занят другим приложением (закройте Zoom, Skype и др.)\n- Микрофон отключён в системе\n- Проблемы с драйверами звука\n\nПопробуйте перезагрузить браузер и проверить микрофон в других приложениях.';
                        break;
                    case 'not-allowed':
                        msg = 'Доступ к микрофону запрещён.\n\nРазрешите доступ в настройках браузера (иконка замка в адресной строке).';
                        break;
                    case 'no-speech':
                        msg = 'Речь не распознана. Говорите громче и чётче, или проверьте микрофон.';
                        break;
                    case 'network':
                        msg = 'Ошибка сети. Проверьте интернет-соединение.';
                        break;
                    default:
                        msg = 'Ошибка распознавания: ' + event.error;
                }
                alert(msg);
                setTimeout(() => {
                    voiceBtn.textContent = '🎙️';
                    voiceBtn.title = 'Голосовой ввод';
                }, 3000);
            };

            recognition.onend = function() {
                voiceBtn.textContent = '🎙️';
                voiceBtn.dataset.listening = 'false';
                voiceBtn.title = 'Голосовой ввод';
            };
        } else {
            const voiceBtn = document.getElementById('quizVoice_' + item.id);
            if (voiceBtn) voiceBtn.style.display = 'none';
        }
        // ===== КЛИК ПО КАРТОЧКЕ (переключение) =====
        card.addEventListener('click', function(e) {
            // ⚙️ Шестерёнка и блок кнопок действий — не переключают режим
            if (e.target.closest('.card-toggle-actions')) return;
            if (e.target.closest('.card-actions')) return;

            if (e.target.closest('.speed-controls') || e.target.closest('.speak-btn') || e.target.closest('.speed-btn')) return;
            if (e.target.closest('.expand-btn')) return;
            if (e.target.closest('.quiz-toggle-wrapper') || e.target.closest('.quiz-input') || e.target.closest('.quiz-check-btn') || e.target.closest('.quiz-hint-btn') || e.target.closest('.quiz-voice-btn')) return;
            
            // ⚡ Проверка флага (если фото-модуль установил)
            if (card._photoClickLock && Date.now() - card._photoClickLock < 300) {
                console.log('🔒 Клик заблокирован флагом фото');
                return;
            }
            // Блокируем клик по карточке в режиме теста
            if (card.classList.contains('quiz-mode')) {
                return; // выходим, не переключая между "Пример" и "Определение"
            }

            // Переключение между "Пример" и "Определение" (как было)
            if (simpleDef.style.display === 'none' || simpleDef.style.display === '') {
                simpleDef.style.display = 'block';
                academicDef.style.display = 'none';
                badge.textContent = 'Пример';
                badge.style.background = '#e6edf6';
                badge.style.color = '#1a2a3a';
                if (metaTags) metaTags.style.display = 'flex';
                card.classList.remove('mode-only-definition');
            } else {
                simpleDef.style.display = 'none';
                academicDef.style.display = 'block';
                badge.textContent = 'Определение';
                badge.style.background = '#0a1929';
                badge.style.color = 'white';
                if (metaTags) metaTags.style.display = 'none';
                card.classList.add('mode-only-definition');
            }
            scheduleUpdateExpandButton(this);
        });

        // ===== РАСКРЫТИЕ =====
        const expandBtn = card.querySelector('.expand-btn');
        expandBtn.addEventListener('click', function(e) {
            e.stopPropagation();
            const currentCard = this.closest('.card');
            currentCard.classList.toggle('expanded');
            this.textContent = currentCard.classList.contains('expanded') ? 'Свернуть ▲' : 'Показать полностью ▼';
            scheduleUpdateExpandButton(currentCard);
        });

        observeCardContent(card);

        /* ============================================================
        СВАЙП КАРТОЧКИ (touch)
        ============================================================ */
        let isDragging = false;
        let startX = 0, startY = 0, currentX = 0;
        let touchStartedHere = false;       // ⚡ тач начался именно на этой карточке

        // Запрещено свайпать при открытом бургер-меню
        function isBurgerOpen() {
            // Проверяем, реально ли открыто меню, а не только класс на body
            const filterGroup = document.getElementById('filterGroup');
            const burgerBtn = document.getElementById('burgerBtn');
            if (!filterGroup || !burgerBtn) return false;

            const isReallyOpen = 
                burgerBtn.classList.contains('active') && 
                filterGroup.classList.contains('open') &&
                getComputedStyle(filterGroup).display !== 'none';

            // Если меню закрыто, но класс остался — убираем его
            if (!isReallyOpen && document.body.classList.contains('burger-open')) {
                document.body.classList.remove('burger-open');
            }

            return isReallyOpen;
        }

        // Что игнорируем при свайпе (все интерактивные элементы)
        function isInteractiveTarget(el) {
            if (!el) return false;
            return !!(el.closest('.card-toggle-actions') ||
                    el.closest('.card-actions') ||
                    el.closest('.speed-controls') ||
                    el.closest('.speak-btn') ||
                    el.closest('.speed-btn') ||
                    el.closest('.expand-btn') ||
                    el.closest('.edit-card-btn') ||
                    el.closest('.delete-card-btn') ||
                    el.closest('.quiz-toggle-wrapper') ||
                    el.closest('.quiz-input') ||
                    el.closest('.quiz-check-btn') ||
                    el.closest('.quiz-hint-btn') ||
                    el.closest('.quiz-voice-btn') ||
                    el.closest('.dropdown-menu') ||
                    el.closest('.cat-menu'));
        }

        card.addEventListener('touchstart', function(e) {
            if (isBurgerOpen()) return;                // ⚡ меню открыто — не свайпаем
            if (isInteractiveTarget(e.target)) return;

            const t = e.touches[0];
            startX = t.clientX;
            startY = t.clientY;
            currentX = 0;
            isDragging = false;
            touchStartedHere = true;
        }, { passive: true });

        card.addEventListener('touchmove', function(e) {
            if (!touchStartedHere) return;
            if (isBurgerOpen()) { touchStartedHere = false; return; }

            const t = e.touches[0];
            const diffX = t.clientX - startX;
            const diffY = t.clientY - startY;

            // Горизонтальный свайп: X > 15px и заметно больше Y
            if (Math.abs(diffX) > 15 && Math.abs(diffX) > Math.abs(diffY) * 1.2) {
                isDragging = true;
                currentX = diffX;

                // ⚡ Отменяем вертикальный скролл страницы — но ТОЛЬКО для этого жеста
                if (e.cancelable) e.preventDefault();

                this.style.transition = 'none';
                this.style.transform = `translateX(${diffX}px) rotate(${diffX / 20}deg)`;
                this.style.opacity = 1 - (Math.abs(diffX) / 500);
            }
        }, { passive: false });   // passive: false нужен для preventDefault

        card.addEventListener('touchend', function(e) {
            if (!touchStartedHere) return;
            touchStartedHere = false;

            if (!isDragging) return;
            isDragging = false;

            this.style.transition = 'transform 0.4s ease, opacity 0.4s ease';

            if (Math.abs(currentX) > 100) {
                const isRight = currentX > 0;
                learnedCards[item.id] = { known: isRight, date: new Date().toISOString() };
                localStorage.setItem('myLearnedCards', JSON.stringify(learnedCards));

                saveResult(item.term, item.category, isRight ? 100 : 0);
                updateDashboard();
                refreshSummary();

                this.style.transform = `translateX(${isRight ? 200 : -200}px)`;
                this.style.opacity = '0';
                setTimeout(() => {
                    this.remove();
                    updateVisibleCount();
                    refreshSummary();
                }, 450);
            } else {
                this.style.transform = '';
                this.style.opacity = '';
                setTimeout(() => { this.style.transition = ''; }, 400);
            }
        }, { passive: true });

        card.addEventListener('touchcancel', function() {
            touchStartedHere = false;
            isDragging = false;
            this.style.transition = '';
            this.style.transform = '';
            this.style.opacity = '';
        }, { passive: true });


        // Pointer-события (для мыши)
        card.addEventListener('pointerdown', function(e) {
            if (e.target.closest('.card-toggle-actions')) return;   // ⚙️
            if (e.target.closest('.card-actions')) return;
            if (e.target.closest('.speed-controls') || e.target.closest('.speak-btn') || e.target.closest('.speed-btn')) return;
            if (e.pointerType === 'touch') return;
            if (e.button !== 0) return;
            if (e.target.closest('.expand-btn')) return;
            if (e.target.closest('.edit-card-btn') || e.target.closest('.delete-card-btn')) return;
            if (e.target.closest('.quiz-toggle-wrapper') || e.target.closest('.quiz-input') || e.target.closest('.quiz-check-btn') || e.target.closest('.quiz-hint-btn') || e.target.closest('.quiz-voice-btn')) return;
            isDragging = false;
            startX = e.clientX;
            startY = e.clientY;
            currentX = 0;
            this.setPointerCapture(e.pointerId);
            // НЕ вызываем preventDefault здесь, чтобы клик мог сработать
        });

        card.addEventListener('pointermove', function(e) {
            if (e.pointerType === 'touch') return;
            if (!this.hasPointerCapture(e.pointerId)) return;
            if (e.target.closest('.card-toggle-actions')) return;   // ⚙️
            if (e.target.closest('.card-actions')) return;
            if (e.target.closest('.expand-btn')) return;
            if (e.target.closest('.edit-card-btn') || e.target.closest('.delete-card-btn')) return;
            if (e.target.closest('.quiz-toggle-wrapper') || e.target.closest('.quiz-input') || e.target.closest('.quiz-check-btn') || e.target.closest('.quiz-hint-btn') || e.target.closest('.quiz-voice-btn')) return;
            const diffX = e.clientX - startX;
            const diffY = e.clientY - startY;
            if (Math.abs(diffX) > 15 && Math.abs(diffX) > Math.abs(diffY) * 1.2) {
                isDragging = true;
                currentX = diffX;
                e.preventDefault();
                this.style.transition = 'none';
                this.style.transform = `translateX(${diffX}px) rotate(${diffX / 20}deg)`;
                this.style.opacity = 1 - (Math.abs(diffX) / 500);
            }
        });

        card.addEventListener('pointerup', function(e) {
            if (e.pointerType === 'touch') return;
            this.releasePointerCapture(e.pointerId);
            if (e.target.closest('.card-toggle-actions')) return;   // ⚙️
            if (e.target.closest('.card-actions')) return;
            if (e.target.closest('.edit-card-btn') || e.target.closest('.delete-card-btn')) return;
            if (e.target.closest('.quiz-toggle-wrapper') || e.target.closest('.quiz-input') || e.target.closest('.quiz-check-btn') || e.target.closest('.quiz-hint-btn') || e.target.closest('.quiz-voice-btn')) return;
            if (!isDragging) {
                this.style.transition = '';
                this.style.transform = '';
                this.style.opacity = '';
                return;
            }
            this.style.transition = 'transform 0.4s ease, opacity 0.4s ease';
            if (Math.abs(currentX) > 100) {
                const isRight = currentX > 0;
                learnedCards[item.id] = { known: isRight, date: new Date().toISOString() };
                localStorage.setItem('myLearnedCards', JSON.stringify(learnedCards));
                
                // ===== ДОБАВЛЕНО: Запись свайпа в статистику =====
                saveResult(item.term, item.category, isRight ? 100 : 0);
                updateDashboard();
                // =================================================

                refreshSummary();
                this.style.transform = `translateX(${isRight ? 200 : -200}px)`;
                this.style.opacity = '0';
                setTimeout(() => {
                    this.remove();
                    updateVisibleCount();
                    refreshSummary();
                }, 450);
            } else {
                this.style.transform = '';
                this.style.opacity = '';
                setTimeout(() => { this.style.transition = ''; }, 400);
            }
            isDragging = false;
        });

        card.addEventListener('pointercancel', function(e) {
            if (e.pointerType === 'touch') return;
            this.releasePointerCapture(e.pointerId);
            this.style.transition = '';
            this.style.transform = '';
            this.style.opacity = '';
            isDragging = false;
        });

        scheduleUpdateExpandButton(card);
    });

    totalCountEl.textContent = uniqueData.length;
    updateVisibleCount();
    refreshSummary();

    setTimeout(() => {
        updateAllVisibleCardsButtons();
    }, 200);
}



